"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Footer: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface FooterLink {
  label: React.ReactNode;
  href: string;
}

export interface FooterColumn {
  title: React.ReactNode;
  links: FooterLink[];
}

const footerVariants = cva(
  "flex w-full flex-col px-12",
  {
    variants: {
      type: {
        simple: "py-8 gap-6",
        columns: "py-12 gap-10",
      },
      theme: {
        light: "bg-surface border-t border-line-default text-fg-primary [&_a]:text-fg-secondary [&_a]:hover:text-fg-primary [&_[data-slot=muted]]:text-fg-tertiary [&_hr]:border-line-default",
        dark: "skin-keep bg-inverse text-fg-inverse [&_a]:opacity-75 [&_a]:hover:opacity-100 [&_[data-slot=muted]]:opacity-60 [&_hr]:border-current/15",
      },
    },
    defaultVariants: {
      type: "simple",
      theme: "light",
    },
  },
);

export interface FooterProps
  extends React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof footerVariants> {
  /** Logo and name. */
  brand?: React.ReactNode;
  /** Short line under the brand (columns type). */
  tagline?: React.ReactNode;
  /** Links next to the brand (simple type). */
  links?: FooterLink[];
  /** Link groups (columns type). */
  columns?: FooterColumn[];
  /** Social icons or links at the end of the bottom bar (columns type). */
  social?: React.ReactNode;
  /** Copyright line. */
  copyright?: React.ReactNode;
}

const Footer = React.forwardRef<HTMLElement, FooterProps>(
  ({ className, type, theme, brand, tagline, links, columns, social, copyright, ...props }, ref) => (
    <footer data-slot="footer" data-kind="surface" ref={ref} className={cn(footerVariants({ type, theme }), className)} {...props}>
      {(type ?? "simple") === "simple" || !columns?.length ? (
        <div className="flex flex-wrap items-center justify-between gap-8">
          <div className="flex items-center gap-2 text-title-medium">{brand}</div>
          <nav aria-label="Footer" className="flex flex-wrap gap-8 text-label-medium">
            {links?.map((link, index) => (
              <a key={index} href={link.href} className="rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
                {link.label}
              </a>
            ))}
          </nav>
        </div>
      ) : (
        <div className="flex flex-wrap items-start gap-12">
          <div className="flex w-80 max-w-full flex-col gap-4">
            <div className="flex items-center gap-2 text-title-medium">{brand}</div>
            {tagline ? <p className="text-body-small">{tagline}</p> : null}
          </div>
          {columns.map((column, index) => (
            <nav key={index} aria-label={typeof column.title === "string" ? column.title : void 0} className="flex min-w-32 flex-1 flex-col gap-3">
              <p data-slot="muted" className="text-label-small uppercase tracking-wide">{column.title}</p>
              {column.links.map((link, linkIndex) => (
                <a key={linkIndex} href={link.href} className="rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus text-body-small">
                  {link.label}
                </a>
              ))}
            </nav>
          ))}
        </div>
      )}
      <hr className="border-0 border-t" />
      <div className="flex flex-wrap items-center justify-between gap-4">
        <p data-slot="muted" className="text-body-small">{copyright}</p>
        {social ? <div className="flex items-center gap-4 [&_svg]:size-5">{social}</div> : null}
      </div>
    </footer>
  ),
);
Footer.displayName = "Footer";

export { Footer, footerVariants };
